function api_tokens():array{if(!is_file(CAL_API_TOKEN_FILE))return [];$v=json_decode((string)file_get_contents(CAL_API_TOKEN_FILE),true);return is_array($v)?$v:[];}
function api_actor():array{$h=(string)($_SERVER['HTTP_AUTHORIZATION']??'');if(!preg_match('/^Bearer\s+(.+)$/i',$h,$m))api_out(['ok'=>false,'error'=>['code'=>'AUTH_REQUIRED','message'=>'Bearer token required.']],401);$raw=trim($m[1]);foreach(api_tokens() as $t){if(empty($t['active']))continue;$hash=(string)($t['token_hash']??'');if($hash!==''&&hash_equals($hash,hash('sha256',$raw)))return $t;}api_out(['ok'=>false,'error'=>['code'=>'AUTH_INVALID','message'=>'Invalid API token.']],401);}
function api_rank(string $r):int{return ['viewer'=>10,'editor'=>20,'admin'=>30][$r]??0;}
function api_need(array $a,string $role):void{if(api_rank((string)($a['role']??'viewer'))<api_rank($role))api_out(['ok'=>false,'error'=>['code'=>'FORBIDDEN','message'=>'Insufficient API role.']],403);}
function api_iso(string $v):string{$v=str_replace(' ','T',trim($v));return strlen($v)===16?$v.':00':$v;}
