function api_forms():array{$d=(array)(df_config()['dataforms']??[]);return ['events'=>max(1,(int)(df_config()['term_dataform_id']??$d['events']??0)),'blocks'=>(int)($d['blocks']??0),'categories'=>(int)($d['categories']??0),'places'=>(int)($d['places']??0),'participants'=>(int)($d['participants']??0),'attachments'=>(int)($d['attachments']??0),'persons'=>(int)($d['persons']??0)];}
function api_form(int $id):array{if($id<1)throw new RuntimeException('Calendar DataForm missing.');$pdo=df_pdo();return [$pdo,df_fields($pdo,$id)];}
function api_find(int $form,int $id):?array{[$pdo,$fields]=api_form($form);return df_find_record($pdo,$form,$id,$fields);}
function api_list_simple(int $form):array{[$pdo,$fields]=api_form($form);$out=[];foreach(df_raw_records($pdo,$form,$fields) as $r){$d=(array)$r['data'];if(array_key_exists('activ',$d)&&(int)$d['activ']!==1)continue;$out[]=['id'=>(int)$r['id']]+$d;}return $out;}
