try{
 $actor=api_actor();$method=strtoupper((string)($_SERVER['REQUEST_METHOD']??'GET'));$path=trim((string)($_SERVER['PATH_INFO']??''),'/');$seg=$path===''?[]:explode('/',$path);$f=api_forms();
 if($path===''||$path==='meta'){api_out(['ok'=>true,'api'=>'easyIT Calendar API','version'=>'1.0','role'=>(string)($actor['role']??'viewer'),'project'=>['id'=>df_project_id(),'name'=>(string)(df_config()['project_name']??'Calendar')],'resources'=>['events','blocks','block-categories','places']]);}
 $resource=$seg[0]??'';$id=isset($seg[1])?(int)$seg[1]:0;
 if($resource==='events'){
   if($method==='GET'){$start=(string)($_GET['start']??'');$end=(string)($_GET['end']??'');[$pdo,$fields]=api_form($f['events']);$rows=[];foreach(df_raw_records($pdo,$f['events'],$fields) as $r){$d=(array)$r['data'];if((int)($d[api_cf('active','activ')]??1)!==1)continue;$x=api_event_payload($d,(int)$r['id']);if($id>0&&(int)$r['id']!==$id)continue;if($start!==''&&substr($x['end'],0,10)<$start)continue;if($end!==''&&substr($x['start'],0,10)>=$end)continue;$rows[]=$x;}if($id>0){if(!$rows)api_out(['ok'=>false,'error'=>['code'=>'NOT_FOUND','message'=>'Event not found.']],404);api_out(['ok'=>true,'data'=>$rows[0]]);}api_out(['ok'=>true,'data'=>$rows]);}
   api_need($actor,'editor');$in=api_body();if($method==='DELETE'){if($id<1)throw new InvalidArgumentException('Event id required.');api_soft_delete($f['events'],$id);api_out(['ok'=>true,'id'=>$id]);}if(!in_array($method,['POST','PUT','PATCH'],true))api_out(['ok'=>false,'error'=>['code'=>'METHOD_NOT_ALLOWED','message'=>'Method not allowed.']],405);[$s,$e]=api_validate_range($in);$eventPersonIds=array_values(array_filter(array_map('intval',(array)($in['person_ids']??[])),static fn(int $v):bool=>$v>0));if(!$eventPersonIds&&$id>0&&$f['participants']>0){foreach(api_list_simple($f['participants']) as $pr)if((int)($pr['event_id']??0)===$id&&(int)($pr['person_id']??0)>0)$eventPersonIds[]=(int)$pr['person_id'];}if(api_overlap_block($s,$e,$eventPersonIds))api_out(['ok'=>false,'error'=>['code'=>'TIME_BLOCKED','message'=>'Requested time overlaps a blocked range.']],409);$old=$id>0?api_find($f['events'],$id):null;if($id>0&&!$old)api_out(['ok'=>false,'error'=>['code'=>'NOT_FOUND','message'=>'Event not found.']],404);$d=$old?(array)$old['data']:[];$d[api_cf('start','start')]=$s;$d[api_cf('end','end')]=$e;$d[api_cf('title','thema')]=mb_substr(trim((string)($in['title']??$in['thema']??'')),0,255);$d[api_cf('description','description')]=(string)($in['description']??'');$d[api_cf('location','location')]=(string)max(0,(int)($in['location_id']??0));$d[api_cf('active','activ')]='1';$d['version_no']=(int)($d['version_no']??0)+1;$new=api_save_simple($f['events'],$d,$id?:null);api_out(['ok'=>true,'id'=>$new],$id?200:201);
 }
 if($resource==='blocks'){
   if($method==='GET'){api_out(['ok'=>true,'data'=>api_list_simple($f['blocks'])]);}api_need($actor,'editor');$in=api_body();if($method==='DELETE'){api_soft_delete($f['blocks'],$id);api_out(['ok'=>true,'id'=>$id]);}[$s,$e]=api_validate_range($in);$cat=max(1,(int)($in['category_id']??0));$person=max(0,(int)($in['person_id']??0));$d=['start'=>$s,'end'=>$e,'category_id'=>(string)$cat,'person_id'=>$person>0?(string)$person:'','reason'=>mb_substr(trim((string)($in['reason']??'')),0,255),'activ'=>'1'];$new=api_save_simple($f['blocks'],$d,$id?:null);api_out(['ok'=>true,'id'=>$new],$id?200:201);
 }
 if($resource==='block-categories'||$resource==='places'){$form=$resource==='places'?$f['places']:$f['categories'];if($method==='GET')api_out(['ok'=>true,'data'=>api_list_simple($form)]);api_need($actor,'admin');$in=api_body();if($method==='DELETE'){api_soft_delete($form,$id);api_out(['ok'=>true,'id'=>$id]);}$allowed=$resource==='places'?['name','description','address','street','postal_code','city','country','room','activ']:['name','description','activ'];$d=[];foreach($allowed as $k)if(array_key_exists($k,$in))$d[$k]=$in[$k];$new=api_save_simple($form,$d,$id?:null);api_out(['ok'=>true,'id'=>$new],$id?200:201);}
 api_out(['ok'=>false,'error'=>['code'=>'NOT_FOUND','message'=>'API resource not found.']],404);
}catch(InvalidArgumentException $e){api_out(['ok'=>false,'error'=>['code'=>'VALIDATION_ERROR','message'=>$e->getMessage()]],400);}catch(Throwable $e){$s=in_array((int)$e->getCode(),[403,404,409],true)?(int)$e->getCode():500;api_out(['ok'=>false,'error'=>['code'=>$s===500?'SERVER_ERROR':'REQUEST_ERROR','message'=>$e->getMessage()]],$s);}
